const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const lon = -112.4685;
    const lat = 34.5400;
    const region = ee.Geometry.Point([lon, lat]).buffer(5000); // 5 km around Prescott
    const start = '2017-06-01';
    const end = '2017-07-01';
    const threshF = 100.0;

    // 2. Data Acquisition & Check with fallback
    let source = 'GRIDMET';
    let scale = 4000; // km-scale
    let col = ee.ImageCollection('IDAHO_EPSCOR/GRIDMET')
      .filterDate(start, end)
      .select('tmmx')
      .map(function(img){ return img.rename('tmax').copyProperties(img, ['system:time_start']); });

    let size = await col.size().getInfo();
    if (size === 0) {
      // Fallback (unlikely needed for CONUS)
      source = 'DAYMET';
      scale = 1000;
      col = ee.ImageCollection('NASA/ORNL/DAYMET_V4')
        .filterDate(start, end)
        .select('tmax');
      size = await col.size().getInfo();
    }

    console.log(`Dataset: ${source}`);
    console.log(`Date Range: ${start} to 2017-06-30`);
    console.log(`Images: ${size}`);
    if (size === 0) {
      console.log('C1');
      return;
    }

    // 3. Pixel count to detect C2
    const first = ee.Image(col.first());
    const countDict = await first.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();
    const pixelCount = countDict ? countDict['tmax'] : null;
    console.log(`Pixel count (first day): ${pixelCount}`);
    if (!pixelCount || pixelCount === 0) {
      console.log('C2');
      return;
    }

    // 4. Daily regional max temperature and stats
    const dailyFC = col.map(function(img) {
      const v = img.reduceRegion({
        reducer: ee.Reducer.max(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('tmax');
      const tF = source === 'GRIDMET'
        ? ee.Number(v).subtract(273.15).multiply(9).divide(5).add(32)
        : ee.Number(v).multiply(9).divide(5).add(32);
      const dateStr = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd');
      return ee.Feature(null, {date: dateStr, tF: tF});
    });

    const temps = await dailyFC.aggregate_array('tF').getInfo();
    const dates = await dailyFC.aggregate_array('date').getInfo();

    let validTemps = [];
    let validDates = [];
    for (let i = 0; i < temps.length; i++) {
      const v = temps[i];
      const d = dates[i];
      if (v !== null && isFinite(v)) {
        if (v < -100 || v > 180) {
          console.log(`Invalid temp detected: ${v} F on ${d}`);
          console.log('C3');
          return;
        }
        validTemps.push(v);
        validDates.push(d);
      }
    }
    if (validTemps.length === 0) {
      console.log('No valid temperature values.');
      console.log('C3');
      return;
    }

    const maxF = validTemps.reduce((a,b)=>Math.max(a,b), -1e9);
    const minF = validTemps.reduce((a,b)=>Math.min(a,b), 1e9);
    let countOver = 0;
    let hottestDay = '';
    let hottestVal = -1e9;
    for (let i = 0; i < validTemps.length; i++) {
      if (validTemps[i] > threshF) countOver++;
      if (validTemps[i] > hottestVal) {
        hottestVal = validTemps[i];
        hottestDay = validDates[i];
      }
    }

    console.log(`Max daily max (F): ${maxF.toFixed(1)} on ${hottestDay}`);
    console.log(`Min daily max (F): ${minF.toFixed(1)}`);
    console.log(`Days > 100 F: ${countOver} of ${validTemps.length}`);

    // 5. Final Answer
    if (countOver > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error(`Error: ${String(err).slice(0,200)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
